import React, {useEffect, useState} from 'react';
import {staticFile, useDelayRender} from 'remotion';
import {loadFont as loadInter} from '@remotion/google-fonts/Inter';
import {loadFont as loadJetBrainsMono} from '@remotion/google-fonts/JetBrainsMono';
import {loadFont as loadSora} from '@remotion/google-fonts/Sora';
import {VENDORED_FONTS} from './vendoredFonts';

export {FONTS} from '../config/theme';

/**
 * Fonts: Sora (headings, buttons, nav, captions), Inter (UI body), JetBrains Mono (code, timings).
 *
 * Two loading paths, chosen by src/lib/vendoredFonts.ts (generated by `npm run assets`):
 *  - vendored: woff2 files from public/fonts/ are loaded with the FontFace API (fully offline renders)
 *  - fallback: @remotion/google-fonts (needs internet the first time)
 * The public exports (FONT_FAMILIES, fontsReady, FontsReady) are identical in both cases.
 */

/** Family names exactly as they are registered in the browser. */
export const FONT_FAMILIES = {
  sora: 'Sora',
  inter: 'Inter',
  mono: 'JetBrains Mono',
} as const;

const loadVendored = (): Promise<void> => {
  const faces = VENDORED_FONTS.map(async (font) => {
    const face = new FontFace(font.family, `url(${staticFile(`fonts/${font.file}`)}) format('woff2')`, {
      weight: String(font.weight),
      style: 'normal',
      display: 'block',
    });
    await face.load();
    document.fonts.add(face);
  });
  return Promise.all(faces).then(() => undefined);
};

const loadFromGoogle = (): Promise<void> => {
  const sora = loadSora('normal', {weights: ['600', '700', '800'], subsets: ['latin']});
  const inter = loadInter('normal', {weights: ['400', '500', '600', '700'], subsets: ['latin']});
  const mono = loadJetBrainsMono('normal', {weights: ['400', '500', '600'], subsets: ['latin']});
  return Promise.all([sora.waitUntilDone(), inter.waitUntilDone(), mono.waitUntilDone()]).then(() => undefined);
};

/** Resolves when all three fonts are ready. */
export const fontsReady: Promise<void> = VENDORED_FONTS.length > 0 ? loadVendored() : loadFromGoogle();

/**
 * Wrap the film in <FontsReady> so frames are never captured before the fonts are loaded.
 * It holds the render open (delayRender) until the fonts resolve, and fails loudly if they cannot load.
 */
export const FontsReady: React.FC<{children: React.ReactNode}> = ({children}) => {
  const {delayRender, continueRender, cancelRender} = useDelayRender();
  const [handle] = useState(() => delayRender('Loading MiniMe fonts (Sora, Inter, JetBrains Mono)'));

  useEffect(() => {
    fontsReady
      .then(() => continueRender(handle))
      .catch((err: unknown) => cancelRender(err));
  }, [handle, continueRender, cancelRender]);

  return React.createElement(React.Fragment, null, children);
};
